import{_ as o,o as t,c as a,ae as i}from"./chunks/framework.Czhw_PXq.js";const h=JSON.parse('{"title":"ADR 006: Proposal Validation & Comparison Logic","description":"","frontmatter":{},"headers":[],"relativePath":"adr/006-proposal-validation.md","filePath":"adr/006-proposal-validation.md"}'),r={name:"adr/006-proposal-validation.md"};function l(n,e,s,c,d,u){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-006-proposal-validation-comparison-logic" tabindex="-1">ADR 006: Proposal Validation &amp; Comparison Logic <a class="header-anchor" href="#adr-006-proposal-validation-comparison-logic" aria-label="Permalink to &quot;ADR 006: Proposal Validation &amp; Comparison Logic&quot;">​</a></h1><ul><li>Status: accepted</li><li>Deciders: Elena, Senior Architect</li><li>Date: 2026-03-04</li></ul><h2 id="context-and-problem-statement" tabindex="-1">Context and Problem Statement <a class="header-anchor" href="#context-and-problem-statement" aria-label="Permalink to &quot;Context and Problem Statement&quot;">​</a></h2><p>We need to validate that a &quot;Technical Proposal&quot; (Oferta) meets the &quot;Mandatory Requirements&quot; extracted from the &quot;Tender Document&quot; (Pliego). The comparison needs to be semantic (understanding meaning), not just keyword matching.</p><h2 id="decision-drivers" tabindex="-1">Decision Drivers <a class="header-anchor" href="#decision-drivers" aria-label="Permalink to &quot;Decision Drivers&quot;">​</a></h2><ul><li><strong>User Experience</strong>: Users need distinct steps (Extract first, then Validate).</li><li><strong>Performance</strong>: Comparing large PDFs against many requirements is expensive.</li><li><strong>Resilience</strong>: Must support the existing Mock/Offline mode.</li></ul><h2 id="decision-outcome" tabindex="-1">Decision Outcome <a class="header-anchor" href="#decision-outcome" aria-label="Permalink to &quot;Decision Outcome&quot;">​</a></h2><p>Chosen option: <strong>&quot;Two-Stage Validation with Use Case Logic&quot;</strong>.</p><h3 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h3><ol><li><strong>Frontend</strong>: <ul><li>Stage 1: Upload Pliego -&gt; Get <code>TenderAnalysis</code> (Requirements).</li><li>Stage 2: Upload Oferta -&gt; Call <code>validateProposal</code> endpoint.</li></ul></li><li><strong>Backend</strong>: <ul><li>Use Case <code>ValidateProposal</code>: Orchestrates the flow.</li><li>Adapter <code>PdfParserAdapter</code>: Reused to parse the Proposal PDF.</li><li>Service <code>OpenAIModelService</code>: Extended with <code>compareProposal(requirement, proposalText)</code>.</li></ul></li></ol><h3 id="logic" tabindex="-1">Logic <a class="header-anchor" href="#logic" aria-label="Permalink to &quot;Logic&quot;">​</a></h3><ul><li>For MVP, we limit validation to the <strong>Top 5 Mandatory Requirements</strong> to save tokens and time.</li><li>The comparison returns a <code>ComparisonResult</code> entity: <ul><li><code>status</code>: MET / NOT_MET</li><li><code>confidence</code>: 0-100%</li><li><code>evidence</code>: Quote from the text (or simulation).</li></ul></li></ul><h3 id="safety-nets" tabindex="-1">Safety Nets <a class="header-anchor" href="#safety-nets" aria-label="Permalink to &quot;Safety Nets&quot;">​</a></h3><ul><li>If OpenAI Quota is exceeded, the service falls back to <code>getMockAnalysis</code> logic which now forces a &quot;COMPLIANT&quot; demo state for visualization.</li></ul>',14)])])}const m=o(r,[["render",l]]);export{h as __pageData,m as default};
